import type { CSSProperties } from 'react';

/** Default motion for Recharts primitives (ms) */
export const CHART_ANIMATION_MS = 780;

export function cartesianGridStroke(isDark: boolean): string {
  return isDark ? 'rgba(255, 255, 255, 0.09)' : 'rgba(15, 23, 42, 0.07)';
}

export type RechartsTooltipConfig = {
  contentStyle: CSSProperties;
  labelStyle: CSSProperties;
  itemStyle: CSSProperties;
  wrapperStyle?: CSSProperties;
};

/** Card-style tooltip that works in light and dark MUI modes */
export function rechartsTooltipProps(isDark: boolean): RechartsTooltipConfig {
  return {
    contentStyle: {
      borderRadius: 12,
      border: isDark ? '1px solid rgba(255, 255, 255, 0.12)' : '1px solid rgba(15, 23, 42, 0.08)',
      backgroundColor: isDark ? 'rgba(30, 41, 59, 0.96)' : 'rgba(255, 255, 255, 0.97)',
      boxShadow: isDark ? '0 12px 36px rgba(0, 0, 0, 0.5)' : '0 12px 32px rgba(15, 23, 42, 0.1)',
      padding: '10px 14px',
    },
    labelStyle: {
      fontWeight: 600,
      marginBottom: 4,
      color: isDark ? '#e2e8f0' : '#0f172a',
      fontSize: 12,
    },
    itemStyle: {
      color: isDark ? '#cbd5e1' : '#334155',
      fontSize: 13,
    },
    wrapperStyle: { outline: 'none' },
  };
}

export const rechartsLegendProps = {
  wrapperStyle: { paddingTop: 8 },
  iconType: 'circle' as const,
  iconSize: 10,
};

export function axisTickForMode(isDark: boolean): { fontSize: number; fill: string } {
  return {
    fontSize: 11,
    fill: isDark ? '#94a3b8' : '#64748b',
  };
}

export const chartAnimationProps = {
  isAnimationActive: true,
  animationDuration: CHART_ANIMATION_MS,
  animationEasing: 'ease-out' as const,
};

/** Pass `prefers-reduced-motion` from `usePrefersReducedMotion()` to disable chart motion. */
export function chartAnimationPropsFor(reducedMotion: boolean) {
  if (reducedMotion) {
    return { isAnimationActive: false, animationDuration: 0, animationEasing: 'linear' as const };
  }
  return chartAnimationProps;
}

